using Didww.Api3.Internal;
using Newtonsoft.Json;

namespace Didww.Api3.Resource.Configuration.SmsTrunkConfiguration;

/// <summary>
/// Outbound messages are submitted to DIDWW over HTTP. The submit URL is
/// returned in the trunk's meta (<see cref="SmsTrunk.Host"/>).
/// <see cref="AuthName"/> and <see cref="AuthPassword"/> are generated by
/// DIDWW and are never sent in a request. (API 2026-10-22)
/// </summary>
public class HttpOutConfiguration : SmsTrunkConfigurationBase
{
    [JsonIgnore]
    public override string ConfigurationType => "http_out";

    /// <summary>URL the status events of messages submitted through the trunk are sent to.</summary>
    [JsonProperty("callback_url")]
    public string? CallbackUrl { get; set; }

    /// <summary>Addresses messages are accepted from.</summary>
    [JsonProperty("allowed_ips")]
    public List<string>? AllowedIps { get; set; }

    /// <summary>Generated HTTP username. Read-only: never sent in a request.</summary>
    [JsonProperty("auth_name")]
    public string? AuthName { get; set; }

    /// <summary>Generated HTTP password. Read-only: never sent in a request.</summary>
    [JsonProperty("auth_password")]
    public string? AuthPassword { get; set; }

    // The default ToString redacts the generated credentials. The wire
    // payload is unaffected (the converter strips them from requests).
    public override string ToString()
    {
        var ips = AllowedIps == null ? "null" : $"[{string.Join(", ", AllowedIps)}]";
        return $"HttpOutConfiguration(CallbackUrl={CallbackUrl ?? "null"}, AllowedIps={ips}, " +
               $"AuthName={Redact.Mask(AuthName)}, AuthPassword={Redact.Mask(AuthPassword)})";
    }
}
